#include "translucent_range_order_candidate.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");ModelRenderInputsCandidate in;in.materials.resize(2);in.materials[1].translucent=true;in.indices={0,0,0,1,1,1,2,2,2,3,3,3};in.ranges={{0,3,1,0,0,0},{3,3,0,0,0,1},{6,3,1,0,0,2},{9,3,1,0,0,3}};std::vector<double>v{1,100,3,3};auto depth=[](double x){return x;};if(translucentRangeOrderCandidate(in,v,depth)!=std::vector<size_t>{2,3,0})throw std::runtime_error("stable back-to-front order");size_t rejected=0;auto reject=[&](auto source,auto vertices){try{translucentRangeOrderCandidate(source,vertices,depth);}catch(const std::runtime_error&){++rejected;}};auto changed=in;changed.ranges[0].firstIndex=100;reject(changed,v);changed=in;changed.indices[0]=100;reject(changed,v);changed=in;changed.ranges[0].materialIndex=100;reject(changed,v);v[0]=std::numeric_limits<double>::quiet_NaN();reject(in,v);if(rejected!=4)throw std::runtime_error("sort rejection");std::cout<<"x64 translucent stable ordering passed rejected="<<rejected<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
